```python
# Function to check if a number is a palindrome
def is_palindrome(n):
    return str(n) == str(n)[::-1]

# Count the number of 3-digit palindromes that are multiples of 3
count = 0
for a in range(1, 10):  # a ranges from 1 to 9
    for b in range(0, 10):  # b ranges from 0 to 9
        palindrome = 100 * a + 10 * b + a
        if palindrome % 3 == 0:
            count += 1

print(count)
```
