H_coordinates = {(3, 0), (2, 1), (1, 2), (0, 3), (-1, 2), (-2, 1), (-3, 0), (-2, -1), (-1, -2), (0, -3), (1, -2), (2, -1)}

# Define the coordinates for each movement (up, down, left, right)
